{
  "name": "typescript-workspace",
  "version": "1.0.0",
  "type": "module",
  "scripts": {
    "build": "tsc",
    "test": "node --test"
  },
  "devDependencies": {
    "typescript": "^5.4.0",
    "@types/node": "^20.11.0"
  }
}

console.log("=====================================================");
console.log("🔷 Welcome to 00 - TypeScript Setup & Toolchain Check!");
console.log("=====================================================");
console.log("✔ TypeScript environment is active and running cleanly!");
console.log("👉 Next: Head over to 01-compiler-and-tsconfig/index.ts");

// 1. noUncheckedIndexedAccess demonstration
const list: string[] = ["alpha", "beta"];
const item = list[0]; // Inferred type: string | undefined (Prevents runtime crashes!)

if (item !== undefined) {
  console.log("Safely accessed item:", item.toUpperCase());
}

// 2. verbatimModuleSyntax enforces 'import type' for type-only imports
console.log("=== 01: Compiler Mastery & Strict tsconfig.json ===");

type RouteConfig = {
  path: string;
  method: "GET" | "POST";
};

// 1. 'satisfies' validates type but PRESERVES exact literal type without broadening
const route = {
  path: "/api/users",
  method: "GET",
} satisfies RouteConfig;

console.log("Exact method literal:", route.method); // Inferred as 'GET'

// 2. 'as const' creates deeply immutable readonly literal structures
const APP_CONFIG = {
  port: 8080,
  env: "production",
  features: ["auth", "billing"],
} as const;

console.log("App Config (Readonly):", APP_CONFIG);

// 1. 'unknown' is the safe top type (requires narrowing before operations)
function processUnknown(val: unknown) {
  if (typeof val === "string") {
    console.log("Narrowed string length:", val.length);
  }
}

// 2. 'never' is the bottom type used for exhaustive checks
type TrafficLight = "RED" | "YELLOW" | "GREEN";

function handleLight(light: TrafficLight): string {
  switch (light) {
    case "RED": return "Stop";
    case "YELLOW": return "Slow";
    case "GREEN": return "Go";
    default: {
      const _exhaustiveCheck: never = light; // Compile error if new variant is added!
      return _exhaustiveCheck;
    }
  }
}

processUnknown("TypeScript 5.x");
console.log("Light handler:", handleLight("GREEN"));

// Declaration Merging (Interfaces only)
interface UserProfile {
  id: string;
  name: string;
}

interface UserProfile {
  email: string; // Merged into UserProfile!
}

const user: UserProfile = {
  id: "usr_1",
  name: "Navnath",
  email: "navnath@example.com",
};

console.log("Merged Interface Profile:", user);

type AsyncState<T> =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "error"; error: Error };

function renderState(state: AsyncState<string>): string {
  switch (state.status) {
    case "idle": return "Ready";
    case "loading": return "Fetching data...";
    case "success": return `Loaded: ${state.data}`;
    case "error": return `Failed: ${state.error.message}`;
  }
}

console.log(renderState({ status: "success", data: "Trak Workspaces" }));

interface Admin { role: "admin"; permissions: string[] }
interface Member { role: "member" }

// Custom Type Predicate
function isAdmin(user: Admin | Member): user is Admin {
  return user.role === "admin" && "permissions" in user;
}

const account: Admin | Member = { role: "admin", permissions: ["write", "delete"] };
if (isAdmin(account)) {
  console.log("Admin permissions:", account.permissions);
}

// Function Overloads
function formatInput(input: string): string;
function formatInput(input: number): string;
function formatInput(input: string | number): string {
  if (typeof input === "string") return `String: ${input.trim()}`;
  return `Number: ${input.toFixed(2)}`;
}

console.log(formatInput("  hello  "));
console.log(formatInput(42.5678));

// Labeled Tuple
type Coordinate = [x: number, y: number, label?: string];

const point: Coordinate = [10, 20, "Origin"];
console.log("Coordinate Point:", point);

// Generics with constraints and const type parameters (TS 5.0+)
function getFirstElement<const T extends readonly unknown[]>(arr: T): T[0] {
  return arr[0];
}

const first = getFirstElement(["apple", "banana"] as const);
console.log("First literal:", first); // Inferred as 'apple'

const Settings = {
  theme: "dark",
  fontSize: 16,
  autoSave: true,
};

type AppSettings = typeof Settings;
type SettingKey = keyof AppSettings; // 'theme' | 'fontSize' | 'autoSave'

function getSetting<K extends SettingKey>(key: K): AppSettings[K] {
  return Settings[key];
}

console.log("Theme setting:", getSetting("theme"));

// Unpack Promise return type with infer
type UnpackPromise<T> = T extends Promise<infer R> ? R : T;

type AsyncResult = UnpackPromise<Promise<{ id: number; token: string }>>;
// AsyncResult resolves to { id: number; token: string }

console.log("=== 11: Conditional Types and the 'infer' Keyword ===");

type User = {
  name: string;
  age: number;
};

// Create Getters mapped type with key remapping
type Getters<T> = {
  [K in keyof T as `get${Capitalize<string & K>}`]: () => T[K];
};

type UserGetters = Getters<User>;
// Inferred as: { getName: () => string; getAge: () => number }

console.log("=== 12: Mapped Types & Key Remapping with 'as' ===");

type EventType = "click" | "hover";
type ElementName = "button" | "input";

type EventName = `on${Capitalize<ElementName>}${Capitalize<EventType>}`;
// 'onButtonClick' | 'onButtonHover' | 'onInputClick' | 'onInputHover'

const eventHandler: EventName = "onButtonClick";
console.log("Valid Event Name:", eventHandler);

interface Product {
  id: string;
  name: string;
  price: number;
  tags: string[];
}

type ProductSummary = Pick<Product, "id" | "name">;
type ProductUpdateInput = Partial<Omit<Product, "id">>;
type PriceMap = Record<string, number>;

const summary: ProductSummary = { id: "p1", name: "Keyboard" };
console.log("Product Summary (Pick):", summary);

class Service {
  // Parameter property automatically initializes this.name and this.port
  constructor(
    public readonly name: string,
    private port: number,
  ) {}

  public getAddress(): string {
    return `http://${this.name}:${this.port}`;
  }
}

const s = new Service("api-gateway", 3000);
console.log("Service Address:", s.getAddress());

// Recommended Modern Pattern: Const Object Union over Enums
export const LogLevel = {
  Debug: "DEBUG",
  Info: "INFO",
  Error: "ERROR",
} as const;

export type LogLevel = typeof LogLevel[keyof typeof LogLevel]; // 'DEBUG' | 'INFO' | 'ERROR'

function log(level: LogLevel, message: string) {
  console.log(`[${level}] ${message}`);
}

log(LogLevel.Info, "System online");

// Type-only imports ensure zero runtime JS bundle footprint
export type DatabaseConfig = {
  host: string;
  port: number;
};

console.log("=== 17: Modules & Type-Only Imports (import type) ===");

declare global {
  interface Window {
    __TRAK_CONFIG__?: { version: string };
  }
}
export {};

# 20 - Runtime Schema Validation (Zod)

```ts
import { z } from "zod";

const UserSchema = z.object({
  id: z.string().uuid(),
  email: z.string().email(),
  age: z.number().int().min(18),
});

type User = z.infer<typeof UserSchema>;
```

type ButtonProps = {
  variant: "primary" | "secondary";
  onClick: () => void;
  children: string;
};

console.log("=== 21: Frontend & React Component Typing ===");

export function add(a: number, b: number): number {
  return a + b;
}

import assert from "node:assert";
import test from "node:test";
import { add } from "./calc.js";

test("adds numbers correctly", () => {
  assert.strictEqual(add(2, 3), 5);
});

