console.log("🎯 23: High-Yield TypeScript Interview Questions & Drills");
console.log("=====================================================");
console.log("1. type vs interface: Declaration merging vs unions/tuples.");
console.log("2. satisfies vs as const: Value preservation vs deep immutability.");
console.log("3. unknown vs any: Safe top type requiring narrowing vs disabling type checker.");
console.log("4. Discriminated unions: Exhaustive pattern matching using common literal tag.");
console.log("5. infer keyword: Unpacking and extracting types in conditional expressions.");
